const C = { navy: "#0D1B2A", surface: "#1B2A41", orange: "#FF7A00", amber: "#FFB347", white: "#F5F5F5", muted: "#A9B4C0", green: "#2ECC71", red: "#E74C3C", border: "#31445F", paper: "#FFF8EC", ink: "#D76500" };
type Mode = "home" | "pos" | "notes" | "calculator" | "receipt" | "more";
