  function sendPosCalcToCart() { const result = Number(calculate(posCalc)); if (!Number.isFinite(result) || result <= 0) return Alert.alert("Amount needed", "Calculate a positive amount before sending it to checkout."); if (!cart.length) return Alert.alert("Start a sale first", "Add at least one product to the cart before sending a payment amount."); setAmountGiven(String(result)); setPosTab("cart"); Alert.alert("Amount sent to cart", `${money(result, state.settings.currency)} is now entered as the amount given.`); }
  async function copyCalc() { await Clipboard.setStringAsync(calc); Alert.alert("Copied", "Calculator result copied locally."); }
  async function exportFile(filename: string, content: string, mimeType = "application/json") { if (Platform.OS === "web") { const blob = new Blob([content], { type: mimeType }); const url = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = url; a.download = filename; a.click(); URL.revokeObjectURL(url); return; } const uri = `${FileSystem.documentDirectory}${filename}`; await FileSystem.writeAsStringAsync(uri, content); if (await Sharing.isAvailableAsync()) await Sharing.shareAsync(uri, { mimeType, dialogTitle: filename }); else Alert.alert("Export saved", uri); }
  async function backup() { await exportFile("shopmate-offline-backup.json", JSON.stringify({ version: 1, exportedAt: new Date().toISOString(), state }, null, 2)); }
  async function restore() { const result = await DocumentPicker.getDocumentAsync({ type: "application/json", copyToCacheDirectory: true }); if (result.canceled) return; try { const raw = await FileSystem.readAsStringAsync(result.assets[0].uri); const parsed = JSON.parse(raw); if (!parsed.state?.products || !parsed.state?.sales) throw new Error("Invalid backup"); setState({ ...parsed.state, receipts: (parsed.state.receipts || []).map((receipt: any) => normalizeReceipt(receipt, parsed.state.settings?.currency || "KSH")) }); Alert.alert("Restore complete", "All local records were restored."); } catch { Alert.alert("Restore failed", "That file is not a valid ShopMate backup."); } }
  async function compressReceiptImage(uri: string) { const image = await ImageManipulator.manipulateAsync(uri, [{ resize: { width: 1080 } }], { compress: 0.7, format: ImageManipulator.SaveFormat.JPEG }); setReceiptImage(image.uri); }
  async function pickBusinessLogo() { const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ["images"], quality: 0.8, allowsEditing: true, aspect: [1, 1] }); if (!result.canceled) { const image = await ImageManipulator.manipulateAsync(result.assets[0].uri, [{ resize: { width: 256, height: 256 } }], { compress: 0.8, format: ImageManipulator.SaveFormat.PNG }); setState(s => ({ ...s, settings: { ...s.settings, businessLogoUri: image.uri } })); } }
  async function pickReceiptImage() { const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ["images"], quality: 0.75, allowsEditing: true }); if (!result.canceled) await compressReceiptImage(result.assets[0].uri); }
  async function takeReceiptPhoto() { const permission = await ImagePicker.requestCameraPermissionsAsync(); if (!permission.granted) return Alert.alert("Camera permission needed", "Allow camera access to capture a receipt image."); const result = await ImagePicker.launchCameraAsync({ quality: 0.75, allowsEditing: true }); if (!result.canceled) await compressReceiptImage(result.assets[0].uri); }
  function addReceiptLine() { const quantity = Number(receiptQty || 0); const unitPrice = Number(receiptPrice || 0); if (!receiptProduct.trim() || quantity <= 0 || unitPrice <= 0) return Alert.alert("Add line details", "Enter an item, quantity, and unit price."); setReceiptLines(lines => [...lines, { description: receiptProduct.trim(), quantity, unitPrice, amount: quantity * unitPrice }]); setReceiptProduct(""); setReceiptQty("1"); setReceiptPrice(""); }
  function addPreviewLine() { const quantity = Number(previewNewQuantity || 0); const unitPrice = Number(previewNewUnitPrice || 0); if (!previewNewDescription.trim() || quantity <= 0 || unitPrice <= 0) return Alert.alert("Add line details", "Enter an item, quantity, and unit price."); setPreviewLines(lines => [...lines, { description: previewNewDescription.trim(), quantity, unitPrice, amount: quantity * unitPrice }]); setPreviewNewDescription(""); setPreviewNewQuantity("1"); setPreviewNewUnitPrice(""); }
  function previewTotals() { const subtotal = previewLines.reduce((sum, line) => sum + line.amount, 0); return calculateReceiptTotals(subtotal, Number(previewDiscount) || 0, previewDiscountMode, Number(previewTax) || 0, previewTaxMode); }
  function saveReceipt() { const lines = receiptLines; const amount = lines.reduce((sum, line) => sum + line.amount, 0); if (!lines.length) return Alert.alert("Add receipt details", "Add at least one line item."); const receipt: ReceiptEntry = { id: freshId("receipt"), receiptNumber: `R-${String(state.receipts.length + 1).padStart(4, "0")}`, title: receiptTitle.trim() || undefined, customerName: receiptCustomer, merchantName: "ShopMate Offline", notes: receiptNotes.trim() || undefined, date: new Date().toISOString(), lines, subtotal: amount, discount: 0, tax: 0, total: amount, source: receiptImage ? "camera" : "manual", images: receiptImage ? [{ id: freshId("receipt-image"), receiptId: "pending", localPath: receiptImage, createdAt: new Date().toISOString() }] : [] }; const savedReceipt = { ...receipt, images: receipt.images.map(image => ({ ...image, receiptId: receipt.id })) }; savedReceipt.thumbnail = buildReceiptThumbnail(savedReceipt, state.settings.currency); setState(s => ({ ...s, receipts: [savedReceipt, ...s.receipts] })); setReceiptLines([]); setReceiptTitle(""); setReceiptNotes(""); setReceiptProduct(""); setReceiptPrice(""); setReceiptQty("1"); setReceiptCustomer(""); setReceiptImage(undefined); Alert.alert("Receipt saved", "Receipt Book is independent from POS stock."); }
  function openReceiptPreview(receipt: ReceiptEntry) { setReceiptPreviewId(receipt.id); setPreviewTitle(receipt.title || ""); setPreviewCustomer(receipt.customerName || ""); setPreviewNotes(receipt.notes || ""); setPreviewDiscount(String(receipt.discount || 0)); setPreviewTax(String(receipt.tax || 0)); setPreviewDiscountMode(receipt.discountMode || "amount"); setPreviewTaxMode(receipt.taxMode || "amount"); setPreviewNewDescription(""); setPreviewNewQuantity("1"); setPreviewNewUnitPrice(""); setPreviewLines(receipt.lines.map(line => ({ ...line }))); }
