  function getPreviewReceipt() { if (!previewReceipt) return undefined; const totals = previewTotals(); return { ...previewReceipt, title: previewTitle.trim() || undefined, customerName: previewCustomer, notes: previewNotes.trim() || undefined, lines: previewLines, subtotal: totals.subtotal, discount: totals.discount, discountMode: previewDiscountMode, tax: totals.tax, taxMode: previewTaxMode, total: totals.total }; }
